/* Research prototype, not a production cryptographic library. Primes are
 * generated by a fresh isolated RSA generator and used only for Paillier. */
import { generateKeyPairSync, randomBytes } from "node:crypto";
const bi = (s) => BigInt("0x" + Buffer.from(s, "base64url").toString("hex"));
export function pow(base, exp, mod) {
  let r = 1n;
  base %= mod;
  for (; exp > 0n; exp >>= 1n, base = (base * base) % mod) if (exp & 1n) r = (r * base) % mod;
  return r;
}
const gcd = (a, b) => {
  while (b) {
    [a, b] = [b, a % b];
  }
  return a;
};
const inv = (a, m) => {
  let [r, s, t, u] = [a, m, 1n, 0n];
  while (s) {
    const q = r / s;
    [r, s] = [s, r - q * s];
    [t, u] = [u, t - q * u];
  }
  if (r !== 1n) throw Error("not invertible");
  return ((t % m) + m) % m;
};
const key = generateKeyPairSync("rsa", { modulusLength: 2048 }).privateKey.export({
  format: "jwk",
});
const p = bi(key.p),
  q = bi(key.q),
  n = p * q,
  n2 = n * n,
  lambda = ((p - 1n) * (q - 1n)) / gcd(p - 1n, q - 1n),
  mu = inv(lambda, n);
function encrypt(m) {
  let r;
  do {
    r = BigInt("0x" + randomBytes(256).toString("hex")) % n;
  } while (r === 0n || gcd(r, n) !== 1n);
  return ((1n + n * BigInt(m)) * pow(r, n, n2)) % n2;
}
function decrypt(c) {
  return (((pow(c, lambda, n2) - 1n) / n) * mu) % n;
}
const ca = encrypt(7),
  cb = encrypt(13);
export const paillierConfig = {
  n: n.toString(),
  ca: ca.toString(),
  cb: cb.toString(),
  keyBits: n.toString(2).length,
  scheme: "Paillier g=n+1 with 2048 bit modulus",
  scope:
    "Affine integer computation only. No general script execution. Experimental implementation.",
};
export const paillierSelfTest = {
  values: [0, 1, 7, 13, 48, 999].map((x) => ({ x, recovered: Number(decrypt(encrypt(x))) })),
  randomizedEncryption: encrypt(7) !== encrypt(7),
};
export function paillierEvaluate(data, bound) {
  if (typeof data.ciphertext !== "string" || !/^\d{1,1240}$/.test(data.ciphertext))
    return { status: 400, error: "Invalid ciphertext encoding" };
  const c = BigInt(data.ciphertext);
  if (c <= 0n || c >= n2 || gcd(c, n) !== 1n)
    return { status: 400, error: "Ciphertext outside group" };
  if (bound) {
    if (!Number.isInteger(data.x) || data.x < 0 || data.x > 99)
      return { status: 400, error: "Input outside domain" };
    if (c !== (pow(ca, BigInt(data.x), n2) * cb) % n2)
      return {
        status: 403,
        error: "Ciphertext is not the allowed expression for the stated input",
      };
  }
  return { status: 200, value: Number(decrypt(c) % 1009n) };
}
